import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CFuv5BrO.js";const b=JSON.parse('{"title":"Hearth OS · 知识本体与指代消解设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/Hearth-知识本体与指代消解设计说明.md","filePath":"architecture/Hearth-知识本体与指代消解设计说明.md","lastUpdated":null}'),o={name:"architecture/Hearth-知识本体与指代消解设计说明.md"};function h(s,t,l,n,c,i){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="hearth-os-·-知识本体与指代消解设计说明" tabindex="-1">Hearth OS · 知识本体与指代消解设计说明 <a class="header-anchor" href="#hearth-os-·-知识本体与指代消解设计说明" aria-label="Permalink to &quot;Hearth OS · 知识本体与指代消解设计说明&quot;">​</a></h1><blockquote><p>本文只依据项目源码整理（<code>apps/server/src</code> 下本体、写回、指代与只读工具相关文件，以及 <code>packages/core/src/personal-agent.ts</code>），未参考 <code>docs/</code> 与 <code>README.md</code>；文中不列举任何具体代码，括号内的文件名仅用于定位核对。 整理日期：2026-11-13</p></blockquote><p><strong>本文边界（避免与本套其它说明重复）</strong></p><table tabindex="0"><thead><tr><th>已讲过的内容</th><th>在哪份文档</th><th>本文的处理</th></tr></thead><tbody><tr><td>经验记忆的捕获、召回打分、巩固、遗忘</td><td><a href="./Hearth-自进化机制设计说明.html">Hearth-自进化机制设计说明</a></td><td>完全不重复</td></tr><tr><td>记忆分层、遗忘与脱敏</td><td><a href="./Hearth-存储设计说明.html">Hearth-存储设计说明</a></td><td>不展开</td></tr><tr><td>上下文包的四车道预算、编译、渲染与按需展开</td><td><a href="./hearth-os-上下文管理设计.html">hearth-os-上下文管理设计</a></td><td>只讲「本体/记忆如何成为候选」，分道与展开交给那篇</td></tr><tr><td>指代澄清如何变成对话追问</td><td><a href="./判定审批机制说明.html">判定审批机制说明</a></td><td>只讲候选打分与歧义判定</td></tr></tbody></table><p>本文只讲：<strong>系统里关于「人、组织、项目、决定、承诺」的那张断言图长什么样，怎么判重、怎么处理冲突、怎么被写回、怎么把一句话里的「他」对上号</strong>。</p><hr><h2 id="_0-一句话总览" tabindex="-1">0. 一句话总览 <a class="header-anchor" href="#_0-一句话总览" aria-label="Permalink to &quot;0. 一句话总览&quot;">​</a></h2><p>本体不是知识图谱数据库，而是一套<strong>基于事件溯源的断言图</strong>：每条断言都带置信度、有效期与证据引用；写操作默认不静默覆盖，遇到矛盾就生成一条待办交给用户裁决。</p><hr><h2 id="_1-先定性-三个容易误解的地方" tabindex="-1">1. 先定性：三个容易误解的地方 <a class="header-anchor" href="#_1-先定性-三个容易误解的地方" aria-label="Permalink to &quot;1. 先定性：三个容易误解的地方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>代码里的实际做法</th></tr></thead><tbody><tr><td>以为本体置信度沿用记忆的「低/中/高」</td><td>是两套独立体系：本体用「推断 / 观察到 / 已确认 / 已失效」，记忆用低中高；只在编译上下文时做一次单向映射</td></tr><tr><td>以为同名实体会自动合并</td><td>判重极保守：只按「名称或别名 + 同类型」命中，类型不同不合并；类型里虽有「合并到谁」字段，实际没有写入路径</td></tr><tr><td>以为「已失效」只是低置信</td><td>它在排序里是<strong>负分</strong>，含义是「证据被遗忘后留下的陈旧断言」，比「推断」还低</td></tr></tbody></table><hr><h2 id="_2-六类断言" tabindex="-1">2. 六类断言 <a class="header-anchor" href="#_2-六类断言" aria-label="Permalink to &quot;2. 六类断言&quot;">​</a></h2><table tabindex="0"><thead><tr><th>断言</th><th>关键内容</th></tr></thead><tbody><tr><td>实体</td><td>稳定标识、十种类型之一、规范名称、状态、敏感度、置信度</td></tr><tr><td>别名</td><td>别名原文与归一化形式、来源类型、置信度</td></tr><tr><td>关系</td><td>起点、谓词（自由文本）、终点、置信度、有效期、证据、被谁取代</td></tr><tr><td>实体状态</td><td>实体 + 键 + 值 + 置信度 + 有效期 + 来源 + 证据 + 被谁取代</td></tr><tr><td>决定</td><td>标题、结论、理由、备选方案、由谁决定（用户 / Agent / 外部）、状态</td></tr><tr><td>承诺</td><td>描述、到期时间、状态（未兑现 / 已履行 / 已违背 / 取消 / 过期）、对方实体、置信度</td></tr></tbody></table><p>别名归一化是一串确定性处理：去首尾空白、转小写、把空白与常见连字符折成空格、合并连续空格。实体状态的值比较用的是「按键排序的递归稳定序列化」，所以对象字段顺序不同不会误判成变化。</p><p>置信度排序固定为：已确认 &gt; 观察到 &gt; 推断 &gt; 已失效。它是「新断言能否盖掉旧断言」的<strong>唯一</strong>依据。</p><hr><h2 id="_3-判重与冲突-宁可问-也不悄悄改" tabindex="-1">3. 判重与冲突：宁可问，也不悄悄改 <a class="header-anchor" href="#_3-判重与冲突-宁可问-也不悄悄改" aria-label="Permalink to &quot;3. 判重与冲突：宁可问，也不悄悄改&quot;">​</a></h2><p><strong>新建实体</strong>：先按规范名称查、再按归一化别名查，且都限定同类型。命中就补一条别名；只有当新断言置信度<strong>更高</strong>时才提升该实体的置信度并发出更新事件，否则原样返回。</p><p><strong>记录状态</strong>：取该实体该键的有效状态（最多 20 条）：</p><table tabindex="0"><thead><tr><th>情况</th><th>处理</th></tr></thead><tbody><tr><td>值相同</td><td>仅当新置信度更高时合并证据与来源，不报冲突</td></tr><tr><td>没有有效状态</td><td>直接写入</td></tr><tr><td>值不同，且显式要求取代，或「新为已确认且旧非已确认」</td><td>让旧状态退休（写失效时间与被谁取代），再写新状态</td></tr><tr><td>值不同，其余情况</td><td>写入一条可被立即替代的冲突状态，并<strong>生成冲突待办</strong></td></tr></tbody></table><p>冲突待办有固定去重键（实体、键、值的哈希），避免反复弹同一件事；固定给出三个选项：保留当前值、采用新值、稍后再说。它会进入注意力队列（治理见<a href="./判定审批机制说明.html">判定审批机制说明</a>）。</p><p>关系按「起点 + 终点 + 谓词」查重，命中即返回，不更新置信度；决定与承诺也各有同题判重规则。另有「遗忘证据」操作：在证据引用里检索受影响的实体，删除证据后把仍活跃但失去支撑的实体置信度置为「已失效」。</p><hr><h2 id="_4-写回-六个入口-只定义「写什么」" tabindex="-1">4. 写回：六个入口，只定义「写什么」 <a class="header-anchor" href="#_4-写回-六个入口-只定义「写什么」" aria-label="Permalink to &quot;4. 写回：六个入口，只定义「写什么」&quot;">​</a></h2><p><code>OntologyWriter</code> 是本体与业务事件之间的桥，有六个入口：</p><table tabindex="0"><thead><tr><th>入口</th><th>写回什么</th></tr></thead><tbody><tr><td>任务结果</td><td>建任务实体并记状态与最新结果；关联目标、产物、所用来源，各建实体与关系</td></tr><tr><td>审批决定</td><td>从审批目标里提取最多五个主题实体，记一条「由用户决定」的决定</td></tr><tr><td>对话轮次</td><td>只处理用户消息：确认句（对/是的/好/记住…）写决定；含时间词与承诺动词的句子解析出到期时间后写承诺</td></tr><tr><td>来源条目</td><td>读正文后建文档实体、记来源状态；从正文抽最多 20 个邮箱建人物实体并记「被提及于」</td></tr><tr><td>用户纠正</td><td>以「已确认 + 允许取代」写状态，并写一条「用户纠正」决定</td></tr><tr><td>证据遗忘</td><td>委托本体的遗忘流程</td></tr></tbody></table><p>相对到期时间的解析支持 ISO 日期、明天、后天、周几、下周，默认时刻是傍晚六点。确认句写的承诺用「已确认」，普通句子用「推断」。</p><blockquote><p>这个文件只定义「写什么」，具体「由哪个事件在什么时候触发」是在服务装配处用回调接线的（见<a href="./Hearth-服务组装与API接入设计说明.html">Hearth-服务组装与API接入设计说明</a>），不在本文展开。</p></blockquote><hr><h2 id="_5-指代消解-把「他-这个项目」对上号" tabindex="-1">5. 指代消解：把「他 / 这个项目」对上号 <a class="header-anchor" href="#_5-指代消解-把「他-这个项目」对上号" aria-label="Permalink to &quot;5. 指代消解：把「他 / 这个项目」对上号&quot;">​</a></h2><p><strong>候选召回</strong>：把所有活跃实体的规范名与别名汇成一张「归一化形式 → 表面写法」的表，在归一化后的输入文本里做子串匹配，按出现位置升序、表面写法长度降序排序，再用区间重叠贪心去重（长串优先，避免「张三」吃掉「张三丰」）。</p><p><strong>打分</strong>是六个分量的加权和：</p><table tabindex="0"><thead><tr><th>分量</th><th>权重</th><th>含义</th></tr></thead><tbody><tr><td>别名匹配</td><td>0.35</td><td>精确别名满分，模糊别名约六成</td></tr><tr><td>时近性</td><td>0.20</td><td>按距今 90 天线性衰减</td></tr><tr><td>范围亲和</td><td>0.15</td><td>是否在当前作用域或同会话历史里出现过</td></tr><tr><td>类型相容</td><td>0.15</td><td>带 @ 或手机号偏人物/账号，公司团队偏组织，项目计划偏项目/主题</td></tr><tr><td>图邻近</td><td>0.10</td><td>是否与作用域实体有一跳关系</td></tr><tr><td>用户确认史</td><td>0.05</td><td>同一归一化写法过去是否被用户确认过</td></tr></tbody></table><p>候选只留前三。<strong>判定为「已解析」需要同时满足两个条件</strong>：最高分不低于 0.75，且要么没有第二名、要么领先第二名至少 0.15。有候选但不满足就是「有歧义」，无候选是「无法解析」。</p><p>只有<strong>不可逆动作</strong>遇到歧义才会阻断执行；消解器本身只返回一段追问文本与候选标签，不负责把追问发出去（对话路由见判定审批文档）。</p><hr><h2 id="_6-五个只读工具" tabindex="-1">6. 五个只读工具 <a class="header-anchor" href="#_6-五个只读工具" aria-label="Permalink to &quot;6. 五个只读工具&quot;">​</a></h2><p>本体被包装成五个 Agent 可调用的只读工具：查实体、查实体状态、查关系、查决定、列承诺。它们统一有参数解析、结果条数上限（50）与输出长度上限（1.6 万字符，超出给截断预览）。</p><p>几个安全细节：查实体支持稳定标识或名称/别名，多个命中会返回「实体有歧义」并列出候选而不是随便挑一个；敏感度为「秘密」的实体状态，值会被置空并标记已脱敏；查实体只返回活跃状态数与关系数，不返回明细。</p><hr><h2 id="_7-作为上下文候选源" tabindex="-1">7. 作为上下文候选源 <a class="header-anchor" href="#_7-作为上下文候选源" aria-label="Permalink to &quot;7. 作为上下文候选源&quot;">​</a></h2><p>编译上下文时，本体会先做「查询里提到了哪些实体」的匹配（归一化名称或别名被查询包含，最多取 20 个），再对命中实体扩展出有效状态与出边关系作为额外候选；每个候选带词法、图关系、时近三个分量参与统一排序。</p><p>记忆进入候选前有严格的召回门槛：未允许召回、被污染、来源不可信、信任等级为零、敏感内容未获许可、已过期，任一命中就排除；纯词法无关且未命中实体也会被跳过。记忆与本体的关联决定图关系分量是否加一。</p><blockquote><p>编译成四车道上下文包、包哈希复用、按需展开的完整机制见<a href="./hearth-os-上下文管理设计.html">hearth-os-上下文管理设计</a>，这里只说明本体与记忆这一侧的准入条件。</p></blockquote><hr><h2 id="_8-只读代码才会发现的事实" tabindex="-1">8. 只读代码才会发现的事实 <a class="header-anchor" href="#_8-只读代码才会发现的事实" aria-label="Permalink to &quot;8. 只读代码才会发现的事实&quot;">​</a></h2><ol><li>本体置信度与记忆置信度是两套体系，且「已失效」是负排序值。</li><li>判重极保守，矛盾默认生成冲突待办而不是覆盖；类型里的合并字段没有实际写入路径。</li><li>指代「已解析」是双阈值，不是单一分数门槛；只有不可逆动作才会因歧义被阻断。</li><li>五个本体工具严格只读，秘密实体的状态值被置空。</li><li>记忆关联实体时发出的事件里，关系字段用的词与类型定义允许的取值并不一致；所幸上下文编译只关心是否命中实体、不读该字段。</li></ol><hr><h2 id="_9-与其它模块的分界" tabindex="-1">9. 与其它模块的分界 <a class="header-anchor" href="#_9-与其它模块的分界" aria-label="Permalink to &quot;9. 与其它模块的分界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>内容</th></tr></thead><tbody><tr><td>输入</td><td>存储层的实体/关系/决定/承诺查询与事件追加、任务与审批记录、聊天消息、来源条目</td></tr><tr><td>输出</td><td>断言与更新事件、冲突待办、指代解析结果、五个只读工具、上下文候选</td></tr><tr><td>不讲</td><td>记忆的召回巩固遗忘（自进化）、上下文编译分道（上下文）、澄清对话（判定审批）、来源采集（数据源）</td></tr></tbody></table><hr><h2 id="附-源码定位索引" tabindex="-1">附：源码定位索引 <a class="header-anchor" href="#附-源码定位索引" aria-label="Permalink to &quot;附：源码定位索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想看什么</th><th>去哪找</th></tr></thead><tbody><tr><td>置信度排序、判重、冲突与遗忘</td><td><code>apps/server/src/ontology.ts</code></td></tr><tr><td>六个写回入口</td><td><code>apps/server/src/ontology-writer.ts</code></td></tr><tr><td>候选召回与六分量打分</td><td><code>apps/server/src/mentions.ts</code></td></tr><tr><td>五个只读工具</td><td><code>apps/server/src/personal-tools.ts</code></td></tr><tr><td>本体与记忆作为上下文候选源</td><td><code>apps/server/src/context-broker.ts</code></td></tr><tr><td>断言类型契约</td><td><code>packages/core/src/personal-agent.ts</code></td></tr></tbody></table>',54)])])}const _=d(o,[["render",h]]);export{b as __pageData,_ as default};
